  private val channel: EventChannel

  init {
    var channelName = "dev.flutter.pigeon.flutter_radio_player_android.RadioPlayerEventApi.onStateChanged"
    if (instanceName.isNotEmpty()) {
      channelName += ".$instanceName"
    }
    channel = EventChannel(messenger, channelName, MessagesPigeonMethodCodec)
  }

  /**
   * Sets the stream handler for this channel, replacing any previous handler.
   *
   * Pass `null` to remove the event channel registration.
   */
  fun setStreamHandler(streamHandler: OnStateChangedStreamHandler?) {
    val internalHandler = streamHandler?.let { MessagesPigeonStreamHandler<RadioPlayerStateMessage>(it) }
    channel.setStreamHandler(internalHandler)
  }
}

abstract class OnStateChangedStreamHandler : MessagesPigeonEventChannelWrapper<RadioPlayerStateMessage> {
  companion object {
    /**
     * Creates and returns a new event channel that calls the provided stream handler.
     *
     * The returned channel can be stored to allow changing or removing the stream handler.
     * If the handler will not be changed for the lifetime of the engine associated with the messenger,
     * the return value can be ignored.
     */
    fun register(messenger: BinaryMessenger, streamHandler: OnStateChangedStreamHandler, instanceName: String = ""): OnStateChangedEventChannel {
      val channel = OnStateChangedEventChannel(messenger, instanceName)
      channel.setStreamHandler(streamHandler)
      return channel
    }
  }

  // Implement methods from MessagesPigeonEventChannelWrapper
  override fun onListen(p0: Any?, sink: PigeonEventSink<RadioPlayerStateMessage>) {}

  override fun onCancel(p0: Any?) {}
}
      
